window.getTekulasLinesByDistrict = function(district) {
    if (!window.tekulasHatVeritabani) return [];
    if (!district || district === 'TÜMÜ') return window.tekulasHatVeritabani;
    return window.tekulasHatVeritabani.filter(function(r) {
        return r.district === district || (district === 'İlçeler Arası' && (r.isDistrict || r.district === 'İlçeler Arası'));
    });
};

window.getTekulasLineById = function(id) {
    if (!window.tekulasHatVeritabani) return null;
    return window.tekulasHatVeritabani.find(function(r) { return r.id === id; }) || null;
};

window.getTekulasLineByHatNo = function(hatNo) {
    if (!window.tekulasHatVeritabani) return null;
    var target = String(hatNo).trim().toLowerCase();
    
    // 1. Exact match on hatNo
    var found = window.tekulasHatVeritabani.find(function(r) {
        return String(r.hatNo).toLowerCase() === target;
    });
    if (found) return found;

    // 2. Exact match at start of rawName (e.g. "26/..." or "26-...")
    found = window.tekulasHatVeritabani.find(function(r) {
        var rx = new RegExp('^' + target + '[\\-\\/\\s]', 'i');
        return rx.test(r.rawName);
    });
    if (found) return found;

    // 3. Match "Hat {target}:"
    found = window.tekulasHatVeritabani.find(function(r) {
        return r.name.toLowerCase().indexOf('hat ' + target + ':') !== -1;
    });
    return found || null;
};
